package com.dy.artisan3d.ui.screen.contact_usimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.error_unknownimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.repository.ContactUsRepositoryimport com.dy.artisan3d.util.toErrorMessageimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.updateimport kotlinx.coroutines.launchclass ContactUsViewModel(    private val contactUsRepository: ContactUsRepository,) : ViewModel() {    private val _uiState = MutableStateFlow(ContactUsUiState())    val uiState = _uiState.asStateFlow()    fun onChangeFullName(s: String) {        _uiState.update { it.copy(fullName = s, isFullNameError = s.isBlank()) }    }    fun onChangeEmail(s: String) {        _uiState.update { it.copy(email = s, isEmailError = s.isBlank()) }    }    fun onChangeMessage(s: String) {        _uiState.update { it.copy(message = s, isMessageError = s.isBlank()) }    }    fun onSendClick() {        val currentState = _uiState.value        val nameBlank = currentState.fullName.isBlank()        val emailBlank = currentState.email.isBlank()        val messageBlank = currentState.message.isBlank()        _uiState.update {            it.copy(                isFullNameError = nameBlank,                isEmailError = emailBlank,                isMessageError = messageBlank            )        }        if (nameBlank || emailBlank || messageBlank) {            return        }        sendDataToServer()    }    private fun sendDataToServer() {        viewModelScope.launch {            _uiState.update { it.copy(isLoading = true) }            try {                val result = contactUsRepository.sendContactUs(                    fullName = uiState.value.fullName.trim(),                    email = uiState.value.email.trim(),                    message = uiState.value.message.trim()                )                _uiState.update {                    it.copy(                        isSuccess = result.getOrThrow().success,                        isLoading = false                    )                }            }catch (e: Exception){                val errorMsg = if (e is NetworkError) {                    e.toErrorMessage()                } else {                    Res.string.error_unknown                }                _uiState.value = _uiState.value.copy(                    isLoading = false,                    isError = true,                    error = errorMsg                )            }        }    }}